<script setup>
import { computed, onBeforeUnmount, reactive, ref, watch } from "vue";
import { useRouter } from "vue-router";
import ErrorState from "@/components/feedback/ErrorState.vue";
import PageContainer from "@/components/layout/PageContainer.vue";
import { createSmartOrder, getSmartSales, searchSmartCustomers } from "@/services/smartSales.js";
import { getCustomerCreditStatus } from "@/services/wholesale.js";
const router = useRouter(); const data = ref(null); const error = ref(null); const loading = ref(false); const saving = ref(false); const search = ref(""); const group = ref(""); const warehouse = ref(""); const priceList = ref(""); const customerSearch = ref(""); const customers = ref([]); const customer = ref(""); const credit = ref(null); const cart = reactive({}); let controller; let timer;
async function loadCredit() { credit.value = null; if (!customer.value) return; try { credit.value = await getCustomerCreditStatus(customer.value, data.value?.company); } catch { credit.value = null; } }
const cartRows = computed(() => Object.values(cart)); const total = computed(() => cartRows.value.reduce((sum, row) => sum + Number(row.qty) * Number(row.rate || 0), 0));
async function load() { controller?.abort(); controller = new AbortController(); loading.value = true; error.value = null; try { data.value = await getSmartSales({ page: 1, page_length: 48, search: search.value, item_group: group.value, warehouse: warehouse.value, price_list: priceList.value }, controller.signal); warehouse.value ||= data.value.warehouses?.[0] || ""; priceList.value ||= data.value.price_list || ""; } catch (caught) { if (caught.name !== "AbortError") error.value = caught; } finally { loading.value = false; } }
function schedule() { clearTimeout(timer); timer = setTimeout(load, 300); }
async function findCustomers() { if (customerSearch.value.trim().length < 2) { customers.value = []; return; } try { customers.value = await searchSmartCustomers(customerSearch.value, controller?.signal); } catch (caught) { error.value = caught; } }
function add(item) { if (!cart[item.item_code]) cart[item.item_code] = { item_code: item.item_code, item_name: item.item_name, rate: item.rate, qty: 1 }; else cart[item.item_code].qty += 1; }
async function save() { if (saving.value) return; if (!customer.value || !warehouse.value || !cartRows.value.length) { error.value = new Error("Choose a customer and warehouse, then add at least one product."); return; } saving.value = true; error.value = null; try { const result = await createSmartOrder({ request_id: crypto.randomUUID(), customer: customer.value, company: data.value.company, warehouse: warehouse.value, price_list: priceList.value, items: cartRows.value.map(({ item_code, qty }) => ({ item_code, qty })) }); await router.push(result.route); } catch (caught) { error.value = caught; } finally { saving.value = false; } }
watch([group, warehouse, priceList], load); watch(customerSearch, () => { clearTimeout(timer); timer = setTimeout(findCustomers, 300); }); watch(customer, loadCredit); load(); onBeforeUnmount(() => { clearTimeout(timer); controller?.abort(); });
</script>
<template><PageContainer><ErrorState v-if="error && !data" title="Unable to load Smart Sales" :message="error.message" @retry="load" /><main v-else class="rug-page"><nav class="rug-breadcrumbs"><RouterLink to="/home">Home</RouterLink><span>›</span><strong>Smart Sales</strong></nav><header class="rug-banner"><div><span class="rug-badge">Guided sales</span><h1>Smart Sales</h1><p>Search the live product catalogue, build a cart and create a standard ERPNext Draft Sales Order.</p></div><button class="rug-primary" type="button" :disabled="saving || !data?.can_create_sales_order" @click="save">{{ saving ? 'Creating…' : 'Create Draft Order' }}</button></header><div v-if="error" class="rug-inline-error">{{ error.message }}</div><section class="rug-section-card"><div class="priority-sales-controls"><label><span>Customer</span><input v-model="customerSearch" type="search" placeholder="Search customers…" /><select v-model="customer"><option value="">Choose customer</option><option v-for="row in customers" :key="row.name" :value="row.name">{{ row.customer_name }} · {{ row.name }}</option></select></label><label><span>Warehouse</span><select v-model="warehouse"><option v-for="value in data?.warehouses || []" :key="value">{{ value }}</option></select></label><label><span>Price List</span><select v-model="priceList"><option v-for="value in data?.price_lists || []" :key="value">{{ value }}</option></select></label></div><div v-if="credit" class="priority-credit-strip" :class="{ 'is-warning': credit.has_overdue || (credit.available_credit !== null && credit.available_credit <= 0) }"><span class="rug-badge">{{ credit.credit_type || 'Credit type not set' }}</span><span>Outstanding: <strong>{{ data?.currency }} {{ Number(credit.current_outstanding || 0).toLocaleString() }}</strong></span><span v-if="credit.credit_limit">Limit: <strong>{{ Number(credit.credit_limit).toLocaleString() }}</strong></span><span v-if="credit.available_credit !== null">Available: <strong>{{ Number(credit.available_credit).toLocaleString() }}</strong></span><span v-if="credit.has_overdue" class="priority-credit-overdue">Overdue: {{ Number(credit.overdue_amount).toLocaleString() }}</span></div></section><div class="priority-sales-layout"><section class="rug-section-card"><header><div><h2>Products</h2><p>Prices and stock availability come from ERPNext.</p></div></header><div class="priority-sales-controls"><label><span>Search</span><input v-model="search" type="search" placeholder="Item code, name, group or brand" @input="schedule" /></label><label><span>Item Group</span><select v-model="group"><option value="">All groups</option><option v-for="value in data?.item_groups || []" :key="value">{{ value }}</option></select></label></div><div v-if="loading" class="rug-skeleton"><i v-for="n in 8" :key="n" /></div><div v-else class="priority-product-grid"><button v-for="item in data?.items || []" :key="item.item_code" type="button" @click="add(item)"><img v-if="item.image" :src="item.image" alt="" /><span v-else class="priority-product-placeholder">◇</span><strong>{{ item.item_name }}</strong><small>{{ item.item_code }} · {{ item.item_group }}</small><b>{{ data.currency }} {{ Number(item.rate || 0).toFixed(2) }}</b><em>{{ Number(item.available_to_sell ?? item.actual_qty ?? 0) }} {{ item.stock_uom }} available to sell</em><small class="priority-stock-detail">Actual {{ Number(item.actual_qty ?? 0) }} · Reserved {{ Number(item.reserved_qty ?? 0) }}</small></button></div></section><aside class="rug-section-card priority-cart"><header><div><h2>Cart</h2><p>{{ cartRows.length }} product lines</p></div></header><div v-if="!cartRows.length" class="rug-muted">Select products to begin.</div><article v-for="row in cartRows" :key="row.item_code"><div><strong>{{ row.item_name }}</strong><small>{{ row.item_code }}</small></div><input v-model.number="row.qty" type="number" min="0.001" step="0.001" /><button type="button" aria-label="Remove item" @click="delete cart[row.item_code]">×</button></article><footer><span>Estimated total</span><strong>{{ data?.currency }} {{ total.toFixed(2) }}</strong></footer></aside></div></main></PageContainer></template>
